/**
 * Inline markdown parsing for vendor/markdown.
 *
 * SECURITY MODEL (read this first):
 * Raw text is HTML-escaped character-by-character (& < > ") BEFORE any tags we
 * generate are inserted. Raw HTML found in the source is NEVER passed through —
 * it is rendered as visible escaped text (deliberate deviation from CommonMark,
 * documented for reviewers). The only HTML in the output is generated by this
 * module from markdown constructs. Link destinations pass through
 * `sanitizeUrl`, which allows only http/https/mailto and relative URLs — so
 * `[x](javascript:alert(1))` yields plain escaped text, never a live anchor.
 *
 * Pipeline: the source paragraph becomes a flat array of Cells — either a
 * single escaped text character or an opaque generated-HTML blob. Inline
 * extraction (links/images → code/autolinks/escapes) replaces text cells with
 * generated html cells; emphasis then inserts <em>/<strong>/<br> html cells
 * using CommonMark's delimiter-stack algorithm with per-character eligibility
 * (consumed delimiter characters stay in place but are marked gone, so
 * positions never shift out from under the delimiter list).
 */

const PUNCT = /[!-/:-@[-`{-~¡-¿‐-‧]/;
const SPACE = /\s/;

/** One buffer position: either a raw text char (escaped at assembly) or generated HTML. */
class Cell {
  html: string | null;
  ch: string;
  gone: boolean;
  constructor(html: string | null, ch = '', gone = false) {
    this.html = html;
    this.ch = ch;
    this.gone = gone;
  }
}

const escChar = (c: string): string =>
  c === '&' ? '&amp;' : c === '<' ? '&lt;' : c === '>' ? '&gt;' : c === '"' ? '&quot;' : c;

/** Escape raw text for an HTML text context. The core XSS guard. */
export function escapeText(s: string): string {
  let out = '';
  for (const c of s) out += escChar(c);
  return out;
}

/** Escape for attribute values (also neutralises single quotes defensively). */
export function escapeAttr(s: string): string {
  return escapeText(s).replace(/'/g, '&#39;');
}

/**
 * Link hygiene: allow http(s), mailto, and relative URLs (path, query,
 * fragment). Everything else — javascript:, data:, vbscript:, file:,
 * scheme-like obfuscation such as `java\nscript:` — is rejected, as are
 * protocol-relative `//host` URLs.
 */
export function sanitizeUrl(raw: string): string | null {
  /* eslint-disable-next-line no-control-regex -- stripping NUL/control chars
   * and spaces is the point: it defeats `java\0script:` style obfuscation. */
  const url = raw.trim().replace(/[\u0000- ]/g, '');
  if (url === '') return '';
  if (url.startsWith('//')) return null;
  const schemeMatch = /^[A-Za-z][A-Za-z0-9+.-]*(?::|%3A)/.test(url);
  const colon = url.search(/[:%3a]/i);
  const slash = url.search(/[/\\?#]/);
  const hasScheme = schemeMatch || (colon !== -1 && (slash === -1 || colon < slash));
  if (!hasScheme) return url; // relative
  if (/^(https?:|mailto:)/i.test(url)) return url;
  return null;
}

/* These use the `g` flag (search forward from lastIndex), NOT `y` (match only
 * AT lastIndex): a sticky flag made every link/image invisible unless it sat
 * at column 0 of the paragraph, and made AUTOLINK/RAW_HTML `index === pos`
 * checks vacuous. Callers always set `lastIndex` before `exec` and, where
 * position matters, compare `m.index === pos` explicitly. */
const LINK_RE =
  /\[([^\][]*(?:\[[^\][]*\][^\][]*)*)\]\(\s*(<[^<>\n]*>|[^\s()\\]*(?:\\.[^\s()\\]*)*)(\s+(?:"[^"\n]*"|'[^'\n]*'))?\s*\)/g;
const IMG_RE = /!\[([^\][]*)\]\(\s*(<[^<>\n]*>|[^\s()\\]*(?:\\.[^\s()\\]*)*)(\s+(?:"[^"\n]*"|'[^'\n]*'))?\s*\)/g;
const AUTOLINK_RE = /<(?:((?:https?|mailto):[^\s<>]*)|((?:[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})))>/g;
const RAW_HTML_RE = /<!--[\s\S]*?-->|<\/?[A-Za-z][A-Za-z0-9-]*(?:\s+[^<>]*?)?\/?>/g;
const ESCAPABLE = '\\!"#$%&\'()*+,-./:;<=>?@[]^_`{|}~';

function linkHtml(text: string, dest: string, title: string | null): string {
  const url = sanitizeUrl(dest);
  if (url === null) return escapeText(`[${text}](${dest})`); // unsafe scheme → inert literal
  const t = title !== null ? ` title="${escapeAttr(title)}"` : '';
  return `<a href="${escapeAttr(url)}"${t}>${innerInlineHtml(text)}</a>`;
}

function imageHtml(alt: string, dest: string, title: string | null): string {
  const url = sanitizeUrl(dest);
  if (url === null) return escapeText(`![${alt}](${dest})`);
  const t = title !== null ? ` title="${escapeAttr(title)}"` : '';
  return `<img src="${escapeAttr(url)}" alt="${escapeAttr(alt)}"${t} />`;
}

/** Strip angle brackets / backslash escapes from a link destination. */
function cleanDest(raw: string): string {
  let d = raw;
  if (d.startsWith('<') && d.endsWith('>')) d = d.slice(1, -1);
  return d.replace(/\\([\\!"#$%&'()*+,\-./:;<=>?@[\]^_`{|}~])/g, '$1');
}

function cleanTitle(raw: string | undefined): string | null {
  if (raw === undefined) return null;
  const t = raw.trim();
  return t.length >= 2 ? t.slice(1, -1) : null;
  // Attribute safety note: the title capture group ([^"\n]*) can never
  // contain a raw quote (a `"` aborts the link match → literal text), and
  // linkHtml/imageHtml run the title through escapeAttr, which escapes
  // & < > " ' — so no title can break out of title="…". Verified by tests.
}

/**
 * Pass 1 over a plain string: extract [links](dest "title") and
 * ![images](...). Returns null when nothing matched (caller keeps the string).
 */
function extractLinks(src: string): Cell[] | null {
  const hits: { start: number; end: number; html: string }[] = [];
  let pos = 0;
  while (pos < src.length) {
    IMG_RE.lastIndex = pos;
    const mImg = IMG_RE.exec(src);
    LINK_RE.lastIndex = pos;
    const mLink = LINK_RE.exec(src);
    const hit =
      mImg && mLink
        ? mImg.index <= mLink.index
          ? { m: mImg, img: true }
          : { m: mLink, img: false }
        : mImg
          ? { m: mImg, img: true }
          : mLink
            ? { m: mLink, img: false }
            : null;
    if (!hit) break;
    const html = hit.img
      ? imageHtml(hit.m[1] ?? '', cleanDest(hit.m[2] ?? ''), cleanTitle(hit.m[3]))
      : linkHtml(hit.m[1] ?? '', cleanDest(hit.m[2] ?? ''), cleanTitle(hit.m[3]));
    hits.push({ start: hit.m.index, end: hit.m.index + hit.m[0].length, html });
    pos = hit.m.index + hit.m[0].length;
  }
  if (hits.length === 0) return null;
  const cells: Cell[] = [];
  let last = 0;
  for (const h of hits) {
    for (const c of src.slice(last, h.start)) cells.push(new Cell(null, c));
    cells.push(new Cell(h.html));
    last = h.end;
  }
  for (const c of src.slice(last)) cells.push(new Cell(null, c));
  return cells;
}

/**
 * Pass 2 over one plain-string span: autolinks, raw-HTML-shaped text (escaped,
 * NOT passed through), backslash escapes, backtick code spans. Bare URLs are
 * intentionally NOT auto-linked (subset decision — `<https://…>` autolinks and
 * explicit `[text](url)` are supported).
 */
function extractInlinesSpan(src: string): Cell[] {
  const cells: Cell[] = [];
  const pending: string[] = [];
  const flush = (): void => {
    for (const c of pending.splice(0, pending.length)) cells.push(new Cell(null, c));
  };
  let pos = 0;
  while (pos < src.length) {
    const c = src[pos]!;
    if (c === '<') {
      AUTOLINK_RE.lastIndex = pos;
      const mA = AUTOLINK_RE.exec(src);
      if (mA && mA.index === pos) {
        const href = mA[1] ?? `mailto:${mA[2]}`;
        if (sanitizeUrl(href) === null) {
          pending.push('<');
          pos += 1;
          continue;
        }
        flush();
        cells.push(new Cell(`<a href="${escapeAttr(href)}">${escapeText(mA[1] ?? mA[2]!)}</a>`));
        pos += mA[0].length;
        continue;
      }
      RAW_HTML_RE.lastIndex = pos;
      const mRaw = RAW_HTML_RE.exec(src);
      if (mRaw && mRaw.index === pos) {
        flush();
        // Raw HTML is escaped (shown literally), never emitted as markup.
        cells.push(new Cell(escapeText(mRaw[0])));
        pos += mRaw[0].length;
        continue;
      }
    }
    if (c === '\\' && pos + 1 < src.length) {
      const n = src[pos + 1]!;
      if (ESCAPABLE.includes(n)) {
        // CommonMark: a backslash-escaped punctuation char is a LITERAL, never
        // an emphasis delimiter — emit it as an inert generated cell (the
        // delimiter scanner skips html cells) instead of a text cell.
        flush();
        cells.push(new Cell(escChar(n)));
        pos += 2;
        continue;
      }
      if (n === '\n') {
        pending.push(' ', ' '); // backslash hard break
        pos += 1;
        continue;
      }
    }
    if (c === '`') {
      let n = 0;
      while (src[pos + n] === '`') n++;
      const closeRe = new RegExp('`{' + n + '}(?!`)');
      const rest = src.slice(pos + n);
      const found = closeRe.exec(rest);
      if (found) {
        let code = rest.slice(0, found.index);
        if (code.startsWith(' ') && code.endsWith(' ') && code.trim() !== '') code = code.slice(1, -1);
        flush();
        cells.push(new Cell(`<code>${escapeText(code)}</code>`));
        pos += n + found.index + n;
        continue;
      }
      for (let k = 0; k < n; k++) pending.push('`');
      pos += n;
      continue;
    }
    pending.push(c);
    pos += 1;
  }
  flush();
  return cells;
}

function neighbors(buf: Cell[], before: number, after: number): [string, string] {
  let b = '';
  for (let j = before; j >= 0; j--) {
    const cell = buf[j]!;
    if (cell.html !== null || cell.gone) continue; // opaque/removed: not a flanking char
    b = cell.ch;
    break;
  }
  let a = '';
  for (let j = after; j < buf.length; j++) {
    const cell = buf[j]!;
    if (cell.html !== null || cell.gone) continue;
    a = cell.ch;
    break;
  }
  return [b, a];
}

type Delim = {
  start: number; // index of first run char in buf (mutable across tag insertions)
  len: number; // remaining delimiter chars (mutable)
  origLen: number; // length at scan time (for the rule of 3)
  char: string;
  openable: boolean;
  closeable: boolean;
  dead: boolean; // closer failed the rule of 3 with no fallback — literal
};

/** Scan `*`/`_` delimiter runs over the (pre-emphasis) buffer. Runs never move;
 *  `neighbors` skips consumed chars and generated HTML cells. */
function scanDelims(buf: Cell[]): Delim[] {
  const delims: Delim[] = [];
  for (let i = 0; i < buf.length; i++) {
    const cell = buf[i]!;
    if (cell.html !== null || cell.gone) continue;
    const c = cell.ch;
    if (c !== '*' && c !== '_') continue;
    let end = i;
    while (end < buf.length) {
      const e = buf[end]!;
      if (e.html === null && !e.gone && e.ch === c) end++;
      else break;
    }
    const [before, after] = neighbors(buf, i - 1, end);
    const beforeWs = before === '' || SPACE.test(before);
    const afterWs = after === '' || SPACE.test(after);
    const beforeP = before !== '' && PUNCT.test(before);
    const afterP = after !== '' && PUNCT.test(after);
    const leftFlank = !afterWs && (!afterP || beforeWs || beforeP);
    const rightFlank = !beforeWs && (!beforeP || afterWs || afterP);
    let openable: boolean;
    let closeable: boolean;
    if (c === '_') {
      // intraword `_` is never a delimiter (`snake_case` stays literal)
      openable = leftFlank && !rightFlank;
      closeable = rightFlank && !leftFlank;
    } else {
      openable = leftFlank;
      closeable = rightFlank;
    }
    if (openable || closeable) {
      delims.push({ start: i, len: end - i, origLen: end - i, char: c, openable, closeable, dead: false });
    }
    i = end - 1;
  }
  return delims;
}

function insertCell(buf: Cell[], at: number, html: string, delims: Delim[]): void {
  buf.splice(at, 0, new Cell(html));
  for (const d of delims) if (d.start >= at) d.start += 1;
}

function markGone(buf: Cell[], from: number, count: number): void {
  for (let k = from; k < from + count; k++) buf[k]!.gone = true;
}

/**
 * CommonMark delimiter matching: iterate closers left→right; each pairs with
 * the *nearest* unmatched opener before it, honouring the rule of 3; a closer
 * with leftover length retries (this is how `***x***` → em+strong nests).
 */
function processEmphasis(buf: Cell[]): void {
  const delims = scanDelims(buf);
  let ci = 0;
  while (ci < delims.length) {
    const closer = delims[ci]!;
    if (!closer.closeable || closer.dead || closer.len <= 0) {
      ci++;
      continue;
    }
    let oi = -1;
    let blocked = false;
    for (let j = ci - 1; j >= 0; j--) {
      const cand = delims[j]!;
      if (!cand.openable || cand.dead || cand.len <= 0 || cand.char !== closer.char) continue;
      if (cand.start >= closer.start) continue; // overlapping (same run, already consumed past)
      // CommonMark checks the rule of 3 against the NEAREST eligible opener only.
      const sum = cand.origLen + closer.origLen;
      if (sum % 3 === 0 && !(cand.origLen % 3 === 0 && closer.origLen % 3 === 0)) {
        blocked = true;
      }
      oi = j;
      break;
    }
    if (blocked) {
      if (closer.openable)
        closer.closeable = false; // demote: may still act as an opener
      else closer.dead = true;
      ci++;
      continue;
    }
    if (oi === -1) {
      closer.dead = true;
      ci++;
      continue;
    }
    const opener = delims[oi]!;
    const n = opener.len >= 2 && closer.len >= 2 ? 2 : 1;
    const tag = n === 2 ? 'strong' : 'em';
    // opener consumes the LAST n chars of its run; <tag> lands right after them
    markGone(buf, opener.start + opener.len - n, n);
    insertCell(buf, opener.start + opener.len, `<${tag}>`, delims);
    opener.len -= n;
    if (opener.len === 0) opener.openable = false;
    // rule-of-3 & intervening openers cannot match later closers past this one
    for (let j = oi + 1; j < ci; j++) {
      const mid = delims[j]!;
      if (mid.openable) mid.dead = true;
    }
    // closer consumes the FIRST n chars of its (remaining) run; </tag> before them.
    // NOTE: insertCell() already bumps closer.start by 1 (the run shifted right),
    // so the first consumed char now sits AT closer.start — the earlier `+1`s here
    // were an off-by-one that skipped a delimiter char, ate the following space,
    // and threw on closer runs ending the buffer.
    insertCell(buf, closer.start, `</${tag}>`, delims);
    markGone(buf, closer.start, n);
    closer.start += n;
    closer.len -= n;
    if (closer.len === 0) {
      closer.closeable = false;
      ci++;
    }
    // else: loop retries the same closer with its remaining length
  }
}

/** Assemble the cell buffer: escape text cells, honour hard breaks. */
function assemble(buf: Cell[]): string {
  let html = '';
  let pendingSpaces = 0;
  for (const cell of buf) {
    if (cell.html !== null) {
      html += ' '.repeat(pendingSpaces) + cell.html; // spaces before tags keep words apart
      pendingSpaces = 0;
      continue;
    }
    if (cell.gone) continue;
    const c = cell.ch;
    if (c === ' ') {
      pendingSpaces += 1;
      continue;
    }
    if (c === '\n') {
      if (pendingSpaces >= 2) html = html.trimEnd() + '<br />\n';
      else html += '\n';
      pendingSpaces = 0;
      continue;
    }
    html += ' '.repeat(pendingSpaces) + escChar(c);
    pendingSpaces = 0;
  }
  return html;
}

/** Build the post-extraction cell buffer for a plain string. */
function buildCells(src: string): Cell[] {
  const links = extractLinks(src);
  if (links === null) return extractInlinesSpan(src);
  const cells: Cell[] = [];
  let textRun = '';
  const flushRun = (): void => {
    if (textRun) {
      cells.push(...extractInlinesSpan(textRun));
      textRun = '';
    }
  };
  for (const cell of links) {
    if (cell.html !== null) {
      flushRun();
      cells.push(cell);
    } else {
      textRun += cell.ch;
    }
  }
  flushRun();
  return cells;
}

/** Full inline pipeline for a whole paragraph (public entry via index.ts). */
export function renderInline(src: string): string {
  const buf = buildCells(src);
  processEmphasis(buf);
  return assemble(buf);
}

/** Inner pass used for link text: link syntax inside link text stays literal. */
function innerInlineHtml(text: string): string {
  const buf = extractInlinesSpan(text);
  processEmphasis(buf);
  return assemble(buf);
}
